<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import{get,post,type Row}from'./api';
type Tab='technicians'|'dispatch';type DetailTab='overview'|'profile'|'orders'|'attendance';const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),tab=ref<Tab>('technicians'),detailTab=ref<DetailTab>('overview'),search=ref(''),filter=ref(''),technicians=ref<Row[]>([]),summary=ref<Row>({}),workSummary=ref<Row>({}),dispatch=ref<Row[]>([]),available=ref<Row[]>([]),assignments=reactive<Row>({}),open=ref(false),technician=reactive<Row>({}),orders=ref<Row[]>([]),logs=ref<Row[]>([]);const inputClass='min-h-11 w-full rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-sm text-[var(--nx-text)]';const filtered=computed(()=>{const q=search.value.toLowerCase().trim();return technicians.value.filter(r=>(!filter.value||r.availability_status===filter.value)&&(!q||JSON.stringify(r).toLowerCase().includes(q)));});const fmt=(v:any)=>v?new Date(String(v).replace(' ','T')).toLocaleString('en-PH'):'—';const label=(v:any)=>String(v||'—').replaceAll('_',' ');const tone=(v:any):'success'|'danger'|'warning'|'neutral'=>String(v).toUpperCase()==='AVAILABLE'?'success':['FAILED','CANCELLED'].includes(String(v).toUpperCase())?'danger':['BUSY','ON_SITE','TRAVELING','ON_BREAK','IN_PROGRESS','ASSIGNED'].includes(String(v).toUpperCase())?'warning':'neutral';
async function load(show=false){loading.value=true;error.value='';try{const[d,b]=await Promise.all([get<any>('/api/v1/technician-management'),get<any>('/api/v1/technician-management/dispatch')]);technicians.value=d?.technicians||[];summary.value=d?.summary||{};workSummary.value=d?.work_order_summary||{};dispatch.value=b?.unassigned_work_orders||[];available.value=b?.available_technicians||[];if(show)notice.value='Technician workspace refreshed.';}catch(e){error.value=e instanceof Error?e.message:'Unable to load technicians.';}finally{loading.value=false;}}
async function show(r:Row){busy.value=true;try{const d=await get<any>(`/api/v1/technician-management/technicians/${r.id}`);Object.keys(technician).forEach(k=>delete technician[k]);Object.assign(technician,d?.technician||{});orders.value=d?.work_orders||[];logs.value=d?.attendance_logs||[];detailTab.value='overview';open.value=true;}catch(e){error.value=e instanceof Error?e.message:'Unable to load technician details.';}finally{busy.value=false;}}
async function command(url:string,payload:Row,message:string,confirmText=''){if(confirmText&&!confirm(confirmText))return;busy.value=true;error.value='';try{await post(url,payload);notice.value=message;await load();if(open.value&&technician.id)await show(technician);}catch(e){error.value=e instanceof Error?e.message:'Technician action failed.';}finally{busy.value=false;}}
async function saveProfile(){await command('/api/v1/technician-management/profile',{user_id:technician.id,employee_no:technician.employee_no,mobile_number:technician.mobile_number,service_area:technician.service_area,skill_level:technician.skill_level,vehicle:technician.vehicle,vehicle_plate:technician.vehicle_plate,emergency_contact:technician.emergency_contact,emergency_number:technician.emergency_number,notes:technician.profile_notes},'Technician profile updated.');}async function assign(wo:Row){const id=assignments[wo.id];if(!id)return;await command('/api/v1/technician-management/assign-work-order',{work_order_id:wo.id,technician_id:id},'Work order assigned.','Assign this work order to the selected technician?');}async function orderStatus(wo:Row,status:string){let note='';if(['COMPLETED','FAILED','CANCELLED'].includes(status)){note=prompt(`Required note for ${label(status)}:`)||'';if(!note.trim())return;}await command('/api/v1/technician-management/work-order-status',{work_order_id:wo.id,status,note},`Work order updated to ${label(status)}.`);}
onMounted(()=>void load());
</script>
<template><div class="space-y-4 overflow-x-hidden pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Field operations" title="Technician Management" description="Monitor availability, profiles, workload, attendance, and dispatch readiness."><template #actions><NxButton variant="secondary" :disabled="loading||busy" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="c in [['Total Technicians',summary.total,'Registered technician users'],['Available',summary.available,'Ready for dispatch'],['On Site',summary.on_site,'Currently on field work'],['Offline',summary.offline,'No active attendance today']]" :key="String(c[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{c[0]}}</p><p class="mt-2 text-2xl font-bold">{{c[1]||0}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">{{c[2]}}</p></NxCard></section><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="c in [['Active Jobs',workSummary.active_jobs],['On Site Jobs',workSummary.on_site_jobs],['Completed Today',workSummary.completed_today],['Failed Today',workSummary.failed_today]]" :key="String(c[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{c[0]}}</p><p class="mt-2 text-xl font-bold">{{c[1]||0}}</p></NxCard></section>
<NxToolbar><div class="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between"><div class="flex gap-2" role="tablist"><button v-for="t in [['technicians','Technicians'],['dispatch',`Dispatch Board (${dispatch.length})`]]" :key="t[0]" class="min-h-10 rounded-md px-3 text-sm font-semibold" :class="tab===t[0]?'bg-brand-600 text-white':'bg-[var(--nx-surface-muted)]'" @click="tab=t[0] as Tab">{{t[1]}}</button></div><div v-if="tab==='technicians'" class="flex flex-col gap-2 sm:flex-row"><input v-model="search" placeholder="Search technician…" :class="inputClass+' sm:w-80'"><select v-model="filter" :class="inputClass+' sm:w-56'"><option value="">All Statuses</option><option v-for="s in ['AVAILABLE','BUSY','ON_SITE','TRAVELING','ON_BREAK','OFFLINE']" :key="s">{{label(s)}}</option></select></div></div></NxToolbar>
<NxTableShell v-if="tab==='technicians'" min-width="1100px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Technician</th><th class="px-4 py-3">Employee / Contact</th><th class="px-4 py-3">Availability</th><th class="px-4 py-3">Service Area</th><th class="px-4 py-3">Active Jobs</th><th class="px-4 py-3">Completion</th><th class="px-4 py-3">Last Activity</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="8" class="px-4 py-12 text-center text-[var(--nx-text-muted)]">No technicians found.</td></tr><tr v-for="r in filtered" :key="r.id"><td class="px-4 py-3"><b>{{r.full_name||r.username}}</b><small class="block text-[var(--nx-text-muted)]">{{r.email||r.username}}</small></td><td class="px-4 py-3">{{r.employee_no||'No employee number'}}<small class="block text-[var(--nx-text-muted)]">{{r.mobile_number||r.email||'—'}}</small></td><td class="px-4 py-3"><NxBadge :tone="tone(r.availability_status)">{{label(r.availability_status)}}</NxBadge></td><td class="px-4 py-3">{{r.service_area||'—'}}<small class="block text-[var(--nx-text-muted)]">{{r.skill_level||'JUNIOR'}}</small></td><td class="px-4 py-3 font-bold">{{r.active_work_orders||0}}</td><td class="px-4 py-3">{{r.completion_rate||0}}%<small class="block text-[var(--nx-text-muted)]">{{r.completed_work_orders||0}} completed · {{r.failed_work_orders||0}} failed</small></td><td class="px-4 py-3">{{fmt(r.last_login)}}</td><td class="px-4 py-3"><div class="flex justify-end gap-2"><select :value="r.availability_status" :class="inputClass+' w-36'" @change="command('/api/v1/technician-management/status',{user_id:r.id,status:($event.target as HTMLSelectElement).value},'Availability updated.')"><option v-for="s in ['AVAILABLE','BUSY','ON_SITE','TRAVELING','ON_BREAK']" :key="s">{{label(s)}}</option></select><NxButton variant="secondary" :disabled="busy" @click="show(r)">View</NxButton></div></td></tr></tbody></NxTableShell>
<NxTableShell v-else min-width="1000px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Work Order</th><th class="px-4 py-3">Subscriber</th><th class="px-4 py-3">Type</th><th class="px-4 py-3">Priority</th><th class="px-4 py-3">Schedule</th><th class="px-4 py-3">Assign To</th><th class="px-4 py-3 text-right">Action</th></tr></thead><tbody><tr v-if="!dispatch.length"><td colspan="7" class="px-4 py-12 text-center text-[var(--nx-text-muted)]">No unassigned work orders.</td></tr><tr v-for="r in dispatch" :key="r.id"><td class="px-4 py-3"><b>{{r.work_order_no}}</b><small class="block text-[var(--nx-text-muted)]">{{r.title}}</small></td><td class="px-4 py-3">{{r.subscriber_name||'—'}}<small class="block text-[var(--nx-text-muted)]">{{r.account_number||'—'}}</small></td><td class="px-4 py-3">{{label(r.work_order_type)}}</td><td class="px-4 py-3"><NxBadge :tone="tone(r.priority)">{{r.priority}}</NxBadge></td><td class="px-4 py-3">{{r.scheduled_date||'—'}} {{r.scheduled_time||''}}</td><td class="px-4 py-3"><select v-model="assignments[r.id]" :class="inputClass"><option value="">Select available technician</option><option v-for="t in available" :key="t.id" :value="t.id">{{t.full_name||t.username}} · {{label(t.availability_status)}} · {{t.active_work_orders||0}} active</option></select></td><td class="px-4 py-3 text-right"><NxButton :disabled="busy||!assignments[r.id]" @click="assign(r)">Assign</NxButton></td></tr></tbody></NxTableShell>
<NxModal :open="open" :title="technician.full_name||technician.username||'Technician Details'" :description="`${technician.email||'—'} · ${label(technician.availability_status)}`" max-width="76rem" @close="open=false"><div class="border-b border-[var(--nx-border)] p-4"><div class="flex flex-wrap gap-2"><button v-for="t in [['overview','Overview'],['profile','Profile'],['orders','Work Orders'],['attendance','Attendance Logs']]" :key="t[0]" class="min-h-10 rounded-md px-3 text-sm font-semibold" :class="detailTab===t[0]?'bg-brand-600 text-white':'bg-[var(--nx-surface-muted)]'" @click="detailTab=t[0] as DetailTab">{{t[1]}}</button></div></div><div v-if="detailTab==='overview'" class="grid gap-4 p-5 md:grid-cols-3"><NxCard title="Profile"><dl class="space-y-2 text-sm"><div>Name: <b>{{technician.full_name||'—'}}</b></div><div>Email: <b>{{technician.email||'—'}}</b></div><div>Username: <b>{{technician.username||'—'}}</b></div></dl></NxCard><NxCard title="Today"><dl class="space-y-2 text-sm"><div>Time In: <b>{{fmt(technician.time_in_at)}}</b></div><div>Time Out: <b>{{fmt(technician.time_out_at)}}</b></div><div>Notes: <b>{{technician.notes||'—'}}</b></div></dl></NxCard><NxCard title="Field Information"><dl class="space-y-2 text-sm"><div>Area: <b>{{technician.service_area||'—'}}</b></div><div>Level: <b>{{technician.skill_level||'—'}}</b></div><div>Vehicle: <b>{{technician.vehicle||'—'}} {{technician.vehicle_plate||''}}</b></div></dl></NxCard><NxCard v-for="m in [['Total Jobs',technician.total_work_orders],['Active Jobs',technician.active_work_orders],['Completed',technician.completed_work_orders],['Failed',technician.failed_work_orders],['Success Rate',`${technician.success_rate||0}%`],['Completion Rate',`${technician.completion_rate||0}%`]]" :key="String(m[0])"><p class="text-xs uppercase text-[var(--nx-text-muted)]">{{m[0]}}</p><p class="mt-2 text-xl font-bold">{{m[1]||0}}</p></NxCard></div>
<form v-else-if="detailTab==='profile'" id="tech-profile-form" class="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-3" @submit.prevent="saveProfile"><label v-for="f in [['employee_no','Employee No.'],['mobile_number','Mobile Number'],['service_area','Service Area'],['vehicle','Vehicle'],['vehicle_plate','Plate No.'],['emergency_contact','Emergency Contact'],['emergency_number','Emergency Number'],['profile_notes','Profile Notes']]" :key="f[0]" class="grid gap-2 text-sm font-semibold">{{f[1]}}<input v-model="technician[f[0]]" :class="inputClass"></label><label class="grid gap-2 text-sm font-semibold">Skill Level<select v-model="technician.skill_level" :class="inputClass"><option>JUNIOR</option><option>SENIOR</option><option>LEAD</option></select></label><div class="flex justify-end md:col-span-2 xl:col-span-3"><NxButton type="submit" :disabled="busy">Save Profile</NxButton></div></form>
<div v-else-if="detailTab==='orders'" class="p-5"><NxTableShell min-width="900px"><thead><tr><th class="px-4 py-3">Work Order</th><th class="px-4 py-3">Subscriber</th><th class="px-4 py-3">Type</th><th class="px-4 py-3">Priority</th><th class="px-4 py-3">Status</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!orders.length"><td colspan="6" class="p-8 text-center">No assigned work orders.</td></tr><tr v-for="r in orders" :key="r.id"><td class="px-4 py-3 font-bold">{{r.work_order_no}}</td><td class="px-4 py-3">{{r.subscriber_name}}</td><td class="px-4 py-3">{{label(r.work_order_type||r.type)}}</td><td class="px-4 py-3">{{r.priority}}</td><td class="px-4 py-3"><NxBadge :tone="tone(r.status)">{{label(r.status)}}</NxBadge></td><td class="px-4 py-3"><div class="flex justify-end gap-2"><NxButton v-if="r.status==='ASSIGNED'" variant="secondary" @click="orderStatus(r,'IN_PROGRESS')">Start</NxButton><NxButton v-if="r.status==='IN_PROGRESS'" variant="secondary" @click="orderStatus(r,'ON_SITE')">On Site</NxButton><NxButton v-if="['IN_PROGRESS','ON_SITE'].includes(r.status)" @click="orderStatus(r,'COMPLETED')">Complete</NxButton><NxButton v-if="['IN_PROGRESS','ON_SITE'].includes(r.status)" variant="danger" @click="orderStatus(r,'FAILED')">Failed</NxButton></div></td></tr></tbody></NxTableShell></div>
<div v-else class="p-5"><NxTableShell min-width="800px"><thead><tr><th class="px-4 py-3">Time</th><th class="px-4 py-3">Action</th><th class="px-4 py-3">Old Status</th><th class="px-4 py-3">New Status</th><th class="px-4 py-3">Note</th></tr></thead><tbody><tr v-if="!logs.length"><td colspan="5" class="p-8 text-center">No attendance logs.</td></tr><tr v-for="r in logs" :key="r.id"><td class="px-4 py-3">{{fmt(r.created_at)}}</td><td class="px-4 py-3">{{r.action}}</td><td class="px-4 py-3">{{label(r.old_status)}}</td><td class="px-4 py-3">{{label(r.new_status)}}</td><td class="px-4 py-3">{{r.note||'—'}}</td></tr></tbody></NxTableShell></div><template #footer><NxButton variant="secondary" @click="open=false">Close</NxButton></template></NxModal></div></template>
<style scoped>:global([data-nx-next-root="technicians"]){max-width:100%;overflow-x:hidden}</style>
